void scsi_finish_command(struct scsi_cmnd *cmd) {
    struct Scsi_Host *shost = cmd->device->host;

    if (cmd->host_scribble) {
        spin_lock_irq(shost->host_lock);
        cmd->host_scribble = NULL;
    }

    scsi_remove_async_cmnd(cmd);
    scsi_eh_inc_host_active(shost);
    scsi_eh_up_wait_preempt(shost, NULL, 0);
    cmd->scsi_done(cmd);
}

void scsi_eh_finish_cmd(struct scsi_cmnd *cmd)
{
    struct Scsi_Host *shost = cmd->device->host;

    /*
     * Make sure cmd is not racing with completions from the low-level driver.
     * This is called after abort, so we can safely complete the command here.
     */
    cmd->state = CMD_STATE_EH_DONE;

    /* Remove the command from the pending error handler list */
    list_del_init(&cmd->eh_entry);

    /* Move the command to an appropriate error-handler queue */
    list_add_tail(&cmd->eh_entry, &shost->eh_done_q);

    /* Complete the command */
    scsi_finish_command(cmd);
}

void scsi_eh_done(struct scsi_cmnd *cmd)
{
    struct Scsi_Host *shost = cmd->device->host;

    if (shost->eh_strategy_handler)
        shost->eh_strategy_handler(shost);

    scsi_put_command(cmd);
}

void scsi_finish_aborted_command(struct scsi_cmnd *cmd)
{
    struct Scsi_Host *shost = cmd->device->host;

    cmd->host_scribble = NULL;
    cmd->result = DID_ABORT << 16;
    scsi_io_completion(cmd, 0, 0);
    scsi_remove_from_error_queue(cmd);
    scsi_add_to_error_queue(cmd);
}

void scsi_eh_finish_cmd(struct scsi_cmnd *cmd)
{
    struct Scsi_Host *shost = cmd->device->host;

    if (!cmd->eh_eflags)
        return;

    cmd->scsi_done(cmd);
    scsi_remove_from_error_queue(cmd);
    scsi_queue_insert(cmd, Q_INSERT_REQUEUE);
}
